"""Dependency-free registry for Team manifests and injected implementations."""
from __future__ import annotations

from dataclasses import dataclass

from app.core.contracts import TeamManifest, TeamModule
from app.core.team_availability import TeamContractViolation, TeamUnavailable


class RegistryError(ValueError):
    pass


def _compatible(requested: str, supported: list[str]) -> bool:
    """A contract is compatible only within the same major version."""
    try:
        major = requested.split(".", 1)[0]
        return any(version.split(".", 1)[0] == major for version in supported)
    except (AttributeError, IndexError):
        return False


@dataclass(frozen=True)
class RegisteredTeam:
    manifest: TeamManifest
    module: TeamModule
    # ★register() 에서 한 번만 계산한다. resolve() 는 Case 마다(팀 6개 기준
    #   매 호출) 다시 계산하지 않는다 — 매니페스트는 등록 뒤 안 바뀐다.
    normalized_case_types: frozenset[str]


class TeamRegistry:
    """Maps capabilities to injected Team modules; never imports app.domains."""

    def __init__(self, teams: list[TeamModule] | None = None, *, contract_version: str = "1.0") -> None:
        self.contract_version = contract_version
        self._teams: dict[str, RegisteredTeam] = {}
        self._unavailable: dict[str, str] = {}
        self._declared_capabilities: dict[str, tuple[str, ...]] = {}
        self._known_case_types: dict[str, frozenset[str]] = {}
        for team in teams or []:
            self.register(team)

    def register(self, team: TeamModule) -> TeamManifest:
        manifest = team.manifest
        if not _compatible(self.contract_version, manifest.supported_contract_versions):
            raise RegistryError(f"{manifest.team_id} does not support contract {self.contract_version}")
        if manifest.team_id in self._teams or manifest.team_id in self._unavailable:
            raise RegistryError(f"duplicate team_id: {manifest.team_id}")
        capabilities = tuple(manifest.capabilities)
        if len(set(capabilities)) != len(capabilities):
            raise RegistryError(f"duplicate capability in team: {manifest.team_id}")
        claimed = {capability for values in self._declared_capabilities.values() for capability in values}
        overlap = claimed.intersection(capabilities)
        if overlap:
            raise RegistryError(f"duplicate capability: {', '.join(sorted(overlap))}")
        normalized_case_types = frozenset(value.lower() for value in manifest.accepted_case_types)
        entry = RegisteredTeam(manifest, team, normalized_case_types)
        self._teams[manifest.team_id] = entry
        self._declared_capabilities[manifest.team_id] = capabilities
        return manifest

    def declare_unavailable(self, team_id: str, reason: str, *, manifest=None,
                            capabilities: list[str] | None = None) -> None:
        """Declare an absent plugin without importing or instantiating its code."""
        if reason not in {"disabled", "not_installed", "load_failed", "remote_unavailable"}:
            raise RegistryError(f"invalid team availability reason: {reason}")
        if manifest is not None:
            if manifest.team_id != team_id or manifest.active:
                raise RegistryError("unavailable metadata must identify the same inactive team")
            from types import SimpleNamespace
            self.register(SimpleNamespace(manifest=manifest))
        elif team_id in self._teams:
            if capabilities is not None and tuple(capabilities) != self._declared_capabilities[team_id]:
                raise RegistryError(f"availability cannot change capabilities: {team_id}")
        elif team_id in self._unavailable:
            raise RegistryError(f"duplicate team_id: {team_id}")
        else:
            values = tuple(capabilities or ())
            claimed = {value for items in self._declared_capabilities.values() for value in items}
            if len(set(values)) != len(values) or claimed.intersection(values):
                raise RegistryError(f"duplicate capability for unavailable team: {team_id}")
            self._declared_capabilities[team_id] = values
        self._unavailable[team_id] = reason

    def declare_case_types(self, team_id: str, case_types: list[str] | tuple[str, ...]) -> None:
        """Inject known routing ownership without loading the implementation."""
        if not isinstance(team_id, str) or not team_id.strip():
            raise RegistryError("known routing owner must be nonempty")
        if (not isinstance(case_types, (list, tuple)) or not case_types
                or any(not isinstance(value, str) or not value.strip() for value in case_types)):
            raise RegistryError("known case types must be nonempty strings")
        normalized = frozenset(value.lower() for value in case_types)
        if len(normalized) != len(case_types):
            raise RegistryError(f"duplicate known case type: {team_id}")
        if team_id in self._known_case_types:
            raise RegistryError(f"duplicate known routing owner: {team_id}")
        self._known_case_types[team_id] = normalized

    def availability(self) -> dict[str, dict[str, object]]:
        """Return detached diagnostics for the assembled generation."""
        return {
            team_id: {
                "available": team_id not in self._unavailable and
                team_id in self._teams and self._teams[team_id].manifest.active,
                "reason": self._unavailable.get(team_id) or (
                    "disabled" if team_id in self._teams and not self._teams[team_id].manifest.active else None),
                "capabilities": list(capabilities),
            }
            for team_id, capabilities in self._declared_capabilities.items()
        }

    def require_runnable(self, team_id: str, capability: str | None = None) -> RegisteredTeam:
        """Acquire an implementation only after availability and ownership checks."""
        if team_id in self._unavailable:
            raise TeamUnavailable(team_id, self._unavailable[team_id])
        entry = self._teams.get(team_id)
        if entry is None:
            raise TeamUnavailable(team_id, "not_installed")
        if not entry.manifest.active:
            raise TeamUnavailable(team_id, "disabled")
        if not _compatible(self.contract_version, entry.manifest.supported_contract_versions):
            raise TeamContractViolation(f"{team_id}: incompatible registered contract")
        if capability is not None and capability not in entry.manifest.capabilities:
            raise TeamContractViolation(f"{team_id}: undeclared capability '{capability}'")
        return entry

    def get(self, team_id: str) -> RegisteredTeam:
        try:
            return self._teams[team_id]
        except KeyError as exc:
            raise RegistryError(f"unknown team: {team_id}") from exc

    def resolve(self, *, case_type: str, intent: str | None = None) -> RegisteredTeam:
        """Resolve a case to exactly one active, compatible registered Team.

        ``case_type`` is matched against the manifest's accepted case types.
        When an intent is supplied, an exact capability or a capability in
        that intent namespace (for example ``demo`` -> ``demo.investigate``)
        is preferred.  The registry owns this vocabulary; callers do not need
        to know any Team IDs or capabilities.
        """
        # ★case_type/intent 는 이미 검증된 값이다(classifier 가 INTENTS 밖이면
        #   막는다, feedback.py). 여기서 다시 .lower() 하면 "이 값을 못 믿는다"는
        #   신호를 준다 — 검증된 값을 또 방어하지 않는다.
        case_type = case_type or ""
        intent = intent or None
        if case_type in self._unavailable:
            self.require_runnable(case_type)
        matches = [
            entry for entry in self._teams.values()
            if entry.manifest.active and entry.manifest.team_id not in self._unavailable
            and case_type in entry.normalized_case_types
        ]
        if intent:
            intent_matches = [
                entry for entry in matches
                if any(capability.lower() == intent or capability.lower().startswith(intent + ".")
                       for capability in entry.manifest.capabilities)
            ]
            if intent_matches:
                matches = intent_matches
        if len(matches) != 1:
            if not matches:
                unavailable = [entry.manifest.team_id for entry in self._teams.values()
                               if case_type in entry.normalized_case_types
                               and (not entry.manifest.active or entry.manifest.team_id in self._unavailable)]
                unavailable.extend(team_id for team_id, values in self._declared_capabilities.items()
                                   if team_id in self._unavailable and team_id not in unavailable
                                   and any(value == case_type or value.startswith(case_type + ".") for value in values))
                if len(unavailable) == 1:
                    self.require_runnable(unavailable[0])
                known = [team_id for team_id, values in self._known_case_types.items()
                         if case_type in values]
                if not unavailable and len(known) == 1:
                    self.require_runnable(known[0])
            raise RegistryError(f"case must resolve to exactly one active team: {case_type}")
        return matches[0]

    @staticmethod
    def capability_for(entry: RegisteredTeam, intent: str | None = None, *, input_text: str | None = None,
                       state: dict | None = None) -> str:
        """Return the registered capability selected for a resolved Team."""
        # ★intent(5종, 거친 라벨)만으로는 팀의 capability(팀마다 2~6종,
        #   세분화된 동작) 중 어느 것이 맞는지 못 가른다 — 실측으로 확인된
        #   구체 사례는 docs/reports/debugs/
        #   2026-09-01_capability_for_폴백이_근거없이_기능을_고른다.md 를 본다
        #   (basement 는 그 사례의 업무 어휘를 여기 적지 않는다 — 도메인은
        #   app/domains/ 에 남긴다).
        #
        #   Registry가 문자열 네임스페이스로 대신 추측하지 않는다 — 팀이
        #   자기 capability의 의미를 안다. entry.module이 선택적으로
        #   select_capability(intent, input_text) -> str | None 을 구현하면
        #   그 판단을 먼저 묻는다. None을 돌려주면(또는 아예 구현하지 않으면)
        #   아래 기존 규칙(네임스페이스 매칭 → default_capability →
        #   capabilities[0])으로 그대로 떨어진다 — 하위호환.
        intent = (intent or "").lower() or None
        select = getattr(entry.module, "select_capability", None)
        if callable(select):
            # ★`[결정 2026-09-17]` 세 번째 인자(`state`)를 **선언한 모듈에만** 넘긴다.
            #   두 인자 모듈은 그대로 돈다 — 모든 Team 을 한꺼번에 고치지 않게.
            import inspect

            try:
                accepts_state = len(inspect.signature(select).parameters) >= 3
            except (TypeError, ValueError):
                accepts_state = False
            chosen = (select(intent, input_text or "", dict(state or {})) if accepts_state
                      else select(intent, input_text or ""))
            if chosen is not None:
                if chosen not in entry.manifest.capabilities:
                    raise RegistryError(
                        f"team '{entry.manifest.team_id}'.select_capability returned "
                        f"an undeclared capability: {chosen}"
                    )
                return chosen
        if intent:
            for capability in entry.manifest.capabilities:
                if capability.lower() == intent or capability.lower().startswith(intent + "."):
                    return capability
        return entry.manifest.default_capability or entry.manifest.capabilities[0]

    def manifests(self) -> tuple[TeamManifest, ...]:
        return tuple(entry.manifest for entry in self._teams.values())

"""Operational plugin availability failures, separate from invalid customer input."""
from __future__ import annotations


class TeamUnavailable(RuntimeError):
    code = "team_unavailable"

    def __init__(self, team_id: str, reason: str) -> None:
        self.team_id = team_id
        self.reason = reason
        super().__init__(f"team '{team_id}' is unavailable: {reason}")


class TeamContractViolation(RuntimeError):
    """A registered or remote Team failed its execution contract."""


def unavailable_payload(exc: TeamUnavailable) -> dict:
    """Public domain-neutral error body; HTTP/SSE adapters choose their envelope."""
    return {"error": {
        "code": exc.code, "message": "요청한 업무의 담당 기능을 사용할 수 없습니다",
        "team_id": exc.team_id, "reason": exc.reason,
        "retryable": exc.reason == "remote_unavailable",
    }}

from __future__ import annotations

import asyncio
import inspect
import logging
import math
from datetime import UTC, datetime
from typing import Any

from app.core.contracts import NextAction, TeamResult, TeamTask
from app.core.team_availability import TeamContractViolation, TeamUnavailable
from app.core.remote_team.executor import ToolScopeViolation
from app.core.settings import get_guardrails

logger = logging.getLogger(__name__)


class A2ATeamExecutor:
    """Delegates a TeamTask to an injected A2A transport; no network is owned here."""

    def __init__(self, transport, capability_resolver, *, registry=None, cancel_timeout_seconds=None) -> None:
        self.transport = transport
        self.capability_resolver = capability_resolver
        self.registry = registry
        self.cancel_timeout_seconds = float(
            get_guardrails().get("reliability.a2a_cancel_timeout_seconds")
            if cancel_timeout_seconds is None else cancel_timeout_seconds)
        if not math.isfinite(self.cancel_timeout_seconds) or self.cancel_timeout_seconds <= 0:
            raise ValueError("A2A cancel timeout must be finite and positive")

    @property
    def cleanup_budget_seconds(self) -> float:
        """Task deadline은 실행기가 집행하고 Core는 취소 정리 시간을 보장한다."""
        return self.cancel_timeout_seconds

    async def execute(self, task: TeamTask) -> TeamResult:
        if self.registry is None:
            raise TeamUnavailable(task.team_id, "not_installed")
        entry = self.registry.require_runnable(task.team_id, task.capability)
        if not set(task.allowed_tools) <= set(entry.manifest.allowed_tools):
            raise ToolScopeViolation(f"{task.team_id}: task.allowed_tools is outside the manifest")
        self._transport_method(("submit", "send"))
        self._transport_method(("poll", "get_status"), required=False)
        self._transport_method(("cancel",), required=False)
        # The resolver is captured with this generation's registry. String
        # endpoints remain supported; structured endpoints can assert ownership.
        expired = object()
        endpoint = await self._call_within_deadline(lambda: self._resolve(task), task, timeout_value=expired)
        if endpoint is expired:
            return self._failed(task, "remote_deadline_exceeded")
        if endpoint is None:
            raise TeamUnavailable(task.team_id, "remote_unavailable")
        for field, expected in (("team_id", task.team_id), ("capability", task.capability)):
            actual = endpoint.get(field) if isinstance(endpoint, dict) else getattr(endpoint, field, None)
            if actual is not None and actual != expected:
                raise TeamContractViolation(f"A2A endpoint {field} does not match the task")
        remote = await self._call_within_deadline(lambda: self._submit(endpoint, task), task)
        if remote is None:
            return self._failed(task, "remote_deadline_exceeded")
        while self._status(remote) in {"running", "submitted", "working", "in_progress"}:
            if datetime.now(UTC) >= task.deadline_at:
                await self._cancel_best_effort(remote, task)
                return self._failed(task, "remote_deadline_exceeded")
            next_remote = await self._call_within_deadline(lambda: self._poll(remote, task), task)
            if next_remote is None:
                await self._cancel_best_effort(remote, task)
                return self._failed(task, "remote_deadline_exceeded")
            remote = next_remote
        return self._map(task, remote)

    @staticmethod
    async def _call_within_deadline(make_awaitable, task: TeamTask, *, timeout_value=None):
        remaining = (task.deadline_at - datetime.now(UTC)).total_seconds()
        if remaining <= 0:
            return timeout_value
        try:
            return await asyncio.wait_for(make_awaitable(), timeout=remaining)
        except asyncio.TimeoutError:
            return timeout_value

    async def _cancel_best_effort(self, remote, task: TeamTask) -> bool:
        try:
            cancel = self._transport_method(("cancel",), required=False)
            if cancel is None:
                return False
            await asyncio.wait_for(cancel(remote), timeout=self.cancel_timeout_seconds)
            return True
        except Exception as exc:
            logger.warning("a2a_cancel_failed", extra={
                "error_type": type(exc).__name__, "team_id": task.team_id,
                "task_id": str(task.task_id), "run_id": str(task.run_id),
            })
            return False

    async def _submit(self, endpoint, task):
        return await self._transport_method(("submit", "send"))(endpoint, task)

    async def _resolve(self, task):
        resolver = self.capability_resolver
        if self._is_async_callable(resolver):
            value = await resolver(task.capability)
        else:
            # Only pure lookup is permitted here. Cancellation stops waiting,
            # not the worker thread; no remote submission occurs in that thread.
            worker = asyncio.create_task(asyncio.to_thread(resolver, task.capability))
            try:
                value = await asyncio.shield(worker)
            except asyncio.CancelledError:
                worker.add_done_callback(self._discard_resolution)
                raise
        return await value if inspect.isawaitable(value) else value

    @staticmethod
    def _discard_resolution(worker):
        """Consume a late pure lookup; never execute its returned coroutine."""
        if worker.cancelled():
            return
        try:
            value = worker.result()
        except Exception as exc:
            logger.warning("a2a_late_resolver_failed", extra={"error_type": type(exc).__name__})
            return
        if inspect.iscoroutine(value):
            value.close()
        elif asyncio.isfuture(value):
            value.cancel()

    async def _poll(self, remote, task):
        return await self._transport_method(("poll", "get_status"))(remote, task)

    @staticmethod
    def _is_async_callable(value):
        return inspect.iscoroutinefunction(value) or inspect.iscoroutinefunction(getattr(value, "__call__", None))

    def _transport_method(self, names, *, required=True):
        for name in names:
            method = getattr(self.transport, name, None)
            if method is not None:
                if not callable(method) or not self._is_async_callable(method):
                    raise TeamContractViolation(f"A2A transport {name} must be an async function")
                return method
        if required:
            raise TeamContractViolation(f"A2A transport requires async {names[0]}")
        return None

    @staticmethod
    def _status(remote: Any) -> str:
        value = remote.get("status") if isinstance(remote, dict) else getattr(remote, "status", remote)
        return str(value).lower().replace("-", "_")

    def _map(self, task: TeamTask, remote: Any) -> TeamResult:
        status = self._status(remote)
        failure_code = remote.get("failure_code") if isinstance(remote, dict) else getattr(remote, "failure_code", None)
        if status in {"unavailable", "service_unavailable"} or failure_code == "team_unavailable":
            raise TeamUnavailable(task.team_id, "remote_unavailable")
        data = remote.get("artifact") if isinstance(remote, dict) else getattr(remote, "artifact", None)
        if data is None:
            data = remote.get("result") if isinstance(remote, dict) else getattr(remote, "result", None)
        if data is not None:
            self._validate_result_identity(task, data)
            code = data.get("failure_code") if isinstance(data, dict) else getattr(data, "failure_code", None)
            if code == "team_unavailable":
                raise TeamUnavailable(task.team_id, "remote_unavailable")
        if status in {"input_required", "input_needed", "requires_input", "waiting_for_input"}:
            schema = (remote.get("input_schema") if isinstance(remote, dict) else getattr(remote, "input_schema", None)) or {}
            return TeamResult(task_id=task.task_id, run_id=task.run_id, team_id=task.team_id, outcome="waiting",
                              confidence=0.0, next_action=NextAction.WAIT_FOR_INPUT, wait_reason="customer_input",
                              required_input_schema=schema)
        # ★취소는 실패가 아니다 (v7 DoD-27). 전에는 둘을 같이 묶어
        #   `remote_task_failed` 로 뭉갰다 — **누가 멈췄는지**가 사라진다.
        #   실패는 원격이 못 한 것이고, 취소는 우리가 그만둔 것이다.
        # ★`outcome` 에 "cancelled" 를 넣지 않는다 — 계약 Literal 을 늘리면
        #   전이표·리듀서·저장까지 파급된다. 대신 **원인을 failure_code 로 보존**한다.
        #   v7 이 요구하는 것은 "취소로 **기록**되는가" 이지 새 outcome 값이 아니다.
        if status in {"cancelled", "canceled"}:
            code = (remote.get("failure_code") if isinstance(remote, dict) else getattr(remote, "failure_code", None)) or "cancelled_by_caller"
            return TeamResult(task_id=task.task_id, run_id=task.run_id, team_id=task.team_id,
                              outcome="escalated", confidence=0.0,
                              next_action=NextAction.ESCALATE, failure_code=code,
                              warnings=["원격 Task 가 취소됐다 — 실패와 구분해서 읽어야 한다"])
        if status in {"failed", "error"}:
            code = (remote.get("failure_code") if isinstance(remote, dict) else getattr(remote, "failure_code", None)) or "remote_task_failed"
            return self._failed(task, code)
        if status not in {"completed", "succeeded", "done"}:
            raise TeamContractViolation(f"A2A result has unsupported status: {status}")
        if isinstance(data, TeamResult):
            return data
        if isinstance(data, dict):
            payload = dict(data)
            payload.setdefault("outcome", "completed")
            return TeamResult.model_validate(payload)
        return self._failed(task, "remote_artifact_missing")

    @staticmethod
    def _validate_result_identity(task: TeamTask, result: Any) -> None:
        for field in ("team_id", "task_id", "run_id"):
            value = result.get(field) if isinstance(result, dict) else getattr(result, field, None)
            if value is None or str(value) != str(getattr(task, field)):
                raise TeamContractViolation(f"A2A result {field} does not match the task")

    @staticmethod
    def _failed(task: TeamTask, code: str) -> TeamResult:
        return TeamResult(task_id=task.task_id, run_id=task.run_id, team_id=task.team_id, outcome="failed",
                          confidence=0.0, next_action=NextAction.ESCALATE, failure_code=code)

        entry = self.require_team(owner, case_id=case.get("case_id"))
    else:
        entry = self.registry.resolve(case_type=self._case_type(case), intent=intent)
    capability = self.registry.capability_for(entry, intent,
                                        input_text=(case.get("state_json") or {}).get("customer_input") or case.get("subject"),
                                        state=self._capability_state(case))
    self.require_team(entry.manifest.team_id, capability, case_id=case.get("case_id"))
    return capability

def require_team(self, team_id: str, capability: str | None = None, *, case_id=None):
    """업무 상태와 별개인 운영 기록을 남기고 실행 구현을 획득한다."""
    try:
        return self.registry.require_runnable(team_id, capability)
    except TeamUnavailable as exc:
        logger.warning("team execution unavailable", extra={
            "team_id": exc.team_id, "reason": exc.reason, "case_id": str(case_id or ""),
            "composition_revision": getattr(self, "composition_revision", None),
        })
        raise

def _execution_timeout(self, task: TeamTask) -> float:
    """실행기가 집행하는 마감 뒤의 제한된 정리 예산을 보존한다."""
    cleanup = getattr(self.team_executor, "cleanup_budget_seconds", None)
    if cleanup is None:
        return get_guardrails().get("reliability.team_timeout_seconds")
    try:
        cleanup = float(cleanup)
        grace = float(get_guardrails().get("reliability.team_cleanup_grace_seconds"))
    except (TypeError, ValueError) as exc:
        raise ControllerError("executor cleanup budget and grace must be numeric") from exc
    if not math.isfinite(cleanup) or cleanup < 0 or not math.isfinite(grace) or grace < 0:
        raise ControllerError("executor cleanup budget and grace must be finite and nonnegative")
    remaining = max(0.0, (task.deadline_at - datetime.now(UTC)).total_seconds())
    return remaining + cleanup + grace

async def _execute_team_task(self, task: TeamTask) -> TeamResult:
    timeout = self._execution_timeout(task)
    return await asyncio.wait_for(self.team_executor.execute(task), timeout=timeout)

def _policy(self, tenant_id: str, query: str, scopes: list[str]) -> tuple[list[Any], bool]:
    try:
        return self.policy_search(tenant_id, query, scopes), False
    except Exception:
        # Retrieval failure is an explicit signal to ContextBroker, not an empty result.
        return [], True

def _task(self, case: dict[str, Any], entry, run_id: UUID, *, resume: bool = False,
          resume_node: str | None = None, retrieval_failed: bool = False,
          capability: str | None = None) -> TeamTask:
    # ★`[결정 2026-09-17]` Team 이 정책 근거를 선언했을 때만 RAG 를 돈다.

# -*- coding: utf-8 -*-
"""이동 판정 — 「두 장소 사이를 몇 시에 떠나 · 어떤 경로로 · 얼마나 걸리나」. `[2026-10-06 사용자 요청 — 개인 AI 입구(MCP) 읽기 도구]`

계산은 이미 있는 **이동 판정기**(`team_hooks.legs.leg_planner`)가 한다. 이 파일은 그 결과를 사람(과 개인 AI)이 읽을 모양으로 바꾸고
**못 하는 경우를 그대로 말한다** — 새 판정 · 새 어림 공식을 만들지 않는다.

★결과마다 `grade`(근거 등급)가 붙는다 — **고른 경로가 무엇에 근거하나**로 가른다(`[2026-10-06 코덱스 검토]` 앞 판은 판정기가 경로를 냈다는 이유만으로 모두 시간표라고 했다).
    `timetable`  고른 경로가 **열차(지하철 · 철도)**다(`uses` 에 노선이 있고 버스가 없다 — 열차 단위 시간표로 판정한 것). 어느 시간표 판으로 냈는지(`basis`)와 시간표가 낡았는지(`timetable_stale`)를 같이 싣는다.
                 ★「시간표 판정」이지 **실시간 운행 확정이 아니다**(지연 · 사고는 반영하지 않는다).
    `estimate`   ①고른 경로가 **도보 · 택시 · 버스**(버스가 하나라도 낀 경로)다 — 열차 시간표가 아니다: 도보 · 택시는 거리 · 도로 길찾기로, 버스는 노선 단위 첫차 · 막차 · 배차 **추정**으로 셈한 값이다
                 (도보는 보행망 길찾기가 없으면 직선 거리 × 우회계수 — 어느 쪽인지 판정기가 알려 주지 않는다).
                 ②판정기가 꺼져 있거나 닿지 않아 **직선 거리 어림값**만 낸다(`status=unavailable` — 경로 · 출발 시각은 없다. 지어내지 않는다).
    `none`       판정기가 「이 시각엔 갈 방법이 없다」(막차 뒤 · 첫차 전 …)고 답했다(`status=no_route`) **또는 판단하지 못했다**(`status=undetermined` — 데이터 없음 · 확인 못 함 · 택시 길찾기 불통: 「갈 방법이 없다」는 뜻이 아니다).
                 판정기의 이유를 싣고 **어림값을 덧붙이지 않는다**(판정기가 안 된다고 한 것을 직선 거리로 되살리지 않는다). 이유 문구에서 주소 · 환경변수 · 파일 경로는 가린다(`_scrub`).
  ★대안(`alternatives[]`)에도 경로마다 `grade` 가 붙는다.
★우리 서비스 범위는 서울이다 — 서울 둘레 사각형 밖 좌표는 판정하지 않는다(`status=out_of_scope`, `grade=none`). 이 검사는 판정기 · 근거 조회보다 **먼저** 한다.
★판정기가 예외를 던지거나 이상한 모양을 돌려주면 500 이 아니라 `status=unavailable`(`reason.code=engine_error`) + 직선 어림이다 — 이유는 로그에만 남는다(내부 오류 문구를 내보내지 않는다).
★출발 시각(`depart_at`)을 주면 판정기는 **도착 목표에서 거꾸로** 셈하므로 도착 목표를 `출발 + 90분 → 180분 → 360분` 으로 **최대 셋** 넓혀 가며 첫 성립 경로를 찾는다(앞 판은 90분 하나였다 — 그 안에 도착할 수 없으면 가는 길이 있어도 `no_route`).
  못 찾으면 `no_route` 에 `searched`(어디까지 봤나)를 싣는다 — 6시간 넘게 걸리는 길은 「없다」가 아니라 「안 찾았다」다. 찾은 뒤에는 그 소요에 맞춘 목표로 한 번 더 판정해 출발 시각을 앞으로 당긴다(둘째가 안 되면 첫 결과 — 그것이 가장 이른 출발이라는 보장은 없다).
  `depart_at` 결과에는 `requested_depart_at` 과 `wait_min`(요청 시각 → 판정기가 고른 출발 시각까지 분)이 붙는다. ★둘째 판정이 안 돼 첫 결과를 쓴 경우 `earliest_not_guaranteed=true` —
  판정기는 「가장 늦게 떠나도 되는 후보」를 고르므로 그 출발이 **가장 이른 출발이라는 보장이 없고** `wait_min` 이 첫차 대기가 아니라 탐색 방식 때문에 커졌을 수 있다. 도착 시각(`arrive_by`)이면 한 번만 부른다. 둘 다 안 주면 지금 출발이다.
★바깥 **유료** 소스(Places · Route Matrix)는 이 경로에 없다 — 판정기는 이 서버의 시간표 · 도로 그래프와 **자체 길찾기 서버**(GraphHopper — 설정한 주소를 부른다)만 쓴다(2026-10-06 코드 확인: 이동 판정기 폴더에 Google 호출 없음).
"""
from __future__ import annotations

import logging
import re
from datetime import datetime, timedelta
from typing import Any, Callable

from app.core.service_bindings import current_bindings
from app.core.team_availability import TeamUnavailable

from app.domains.travel_ops.components.conversation.trip_here import SEOUL_BOX
from app.domains.travel_ops.components.planning.replan import distance_m, walk_minutes
from app.domains.travel_ops.components.team_hooks import legs

logger = logging.getLogger(__name__)

GRADE_LABELS = {"timetable": "시간표 기준 판정", "estimate": "어림(시간표 아님)", "none": "근거 없음"}
#: 출발 시각을 줬을 때 도착 목표를 넓혀 가는 단계(분) — 마지막이 「어디까지 봤나」다. ★우리가 고른 값
_TARGET_STEPS_MIN = (90, 180, 360)
#: 판정기가 「판단하지 못했다」는 이유 코드 — 「갈 방법이 없다」가 아니다(데이터 없음 · 확인 못 함 · 택시 길찾기 불통 · 앞당긴 탐색을 못 끝냄)
_UNDETERMINED = frozenset({"no_data", "not_confirmed", "taxi_unavailable", "earliest_unconfirmed"})
#: 주소 · 환경변수 · 파일 경로 — 판정기가 오류 문구에 싣는 내부 정보(GraphHopper 주소 등)가 개인 AI 에게 새지 않게 가린다
_LEAK = re.compile(r"https?://\S+|\b\d{1,3}(?:\.\d{1,3}){3}(?::\d+)?\b|ACOP_\w+|\.env\S*|[A-Za-z]:\\\S+|localhost\S*", re.IGNORECASE)


def _scrub(value: Any) -> Any:
    if isinstance(value, str):
        return _LEAK.sub("<가림>", value)
    if isinstance(value, dict):
        return {k: _scrub(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [_scrub(v) for v in value]
    return value


class InvalidPlace(ValueError):
    """장소를 못 읽었다 — 이름 · 좌표가 없다."""


def as_place(raw: dict[str, Any], *, key: str) -> dict[str, Any]:
    """판정기가 받는 장소 모양(`{key, name, kind, lat, lon, weather_sensitive, attributes}`). 좌표가 숫자가 아니면 `InvalidPlace`."""
    try:
        lat, lon = float(raw["lat"]), float(raw["lon"])
    except (KeyError, TypeError, ValueError):
        raise InvalidPlace("lat · lon 이 필요해요") from None
    if not (-90 <= lat <= 90 and -180 <= lon <= 180):
        raise InvalidPlace("좌표 범위가 맞지 않아요")
    return {"key": key, "name": str(raw.get("name") or "이름 없음")[:80], "kind": "activity", "lat": lat, "lon": lon,
            "weather_sensitive": None, "attributes": {}}


def _in_seoul(place: dict[str, Any]) -> bool:
    lat_min, lat_max, lon_min, lon_max = SEOUL_BOX
    return lat_min <= place["lat"] <= lat_max and lon_min <= place["lon"] <= lon_max


def _grade_of(option: dict[str, Any]) -> str:
    """경로 하나가 무엇에 근거하나 — **열차**(`uses` 에 노선이 있고 버스가 없다)면 시간표, 도보 · 택시 · 버스가 낀 경로면 어림(버스는 노선 단위 배차 추정)."""
    uses = option.get("uses") or []
    if not uses or any(str(u).startswith("버스") for u in uses):
        return "estimate"
    return "timetable"


def _option(option: dict[str, Any]) -> dict[str, Any]:
    return {**{k: option[k] for k in ("id", "label", "eta_min", "walk_m", "fare_krw", "uses") if k in option}, "grade": _grade_of(option)}


def _safe_basis() -> dict[str, Any] | None:
    """판정 근거 — 읽다가 죽어도 판정 자체를 막지 않는다(근거를 모르면 `None`)."""
    try:
        return legs.basis()
    except Exception:                                                  # noqa: BLE001
        logger.exception("move judge: basis unreadable")
        return None


def _valid(got: Any) -> bool:
    """판정기 결과의 모양 — 이상하면 경계에서 거른다."""
    return (isinstance(got, dict) and isinstance(got.get("route"), dict) and isinstance(got.get("starts_at"), datetime)
            and isinstance(got.get("ends_at"), datetime) and isinstance(got.get("eta_min"), (int, float)))


def _judged(got: dict[str, Any], *, tz: Any) -> dict[str, Any]:
    route = got["route"]
    options = [o for o in route.get("options") or [] if isinstance(o, dict)]
    planned = next((o for o in options if o.get("id") == route.get("planned")), None)
    if planned is None:
        raise ValueError("판정기 결과에 고른 경로가 없다")
    local = (lambda m: m.astimezone(tz)) if tz is not None else (lambda m: m)
    grade = _grade_of(planned)
    out = {"status": "judged", "grade": grade, "grade_label": GRADE_LABELS[grade],
           "depart_at": local(got["starts_at"]).isoformat(), "arrive_at": local(got["ends_at"]).isoformat(),
           "eta_min": int(got["eta_min"]), "route": _option(planned),
           "alternatives": [_option(o) for o in options if o.get("id") != route.get("planned")],
           "left_out": [_left_out(e) for e in got.get("left_out") or [] if isinstance(e, dict)]}
    if grade == "estimate":
        out["grade_note"] = "고른 경로가 열차 시간표가 아니라 도보 · 택시(거리 · 도로 길찾기)나 버스(배차 추정)라 어림에 가까운 값이에요"
    return out


def _left_out(entry: dict[str, Any]) -> dict[str, Any]:
    """판정기가 뺀 후보 — 이름 · 코드 · (가린) 이유만 내보낸다."""
    return {k: _scrub(entry[k]) for k in ("label", "code", "reason") if k in entry}


def _estimate(origin: dict[str, Any], dest: dict[str, Any]) -> dict[str, Any]:
    meters = distance_m({"latitude": origin["lat"], "longitude": origin["lon"]}, {"latitude": dest["lat"], "longitude": dest["lon"]})
    return {"straight_line_m": int(round(meters)), "walk_minutes_estimate": walk_minutes(meters),
            "note": "직선 거리로 어림한 값이에요(실제 길 · 시간표가 아니에요)"}


def judge(*, origin: dict[str, Any], dest: dict[str, Any], now: datetime, depart_at: datetime | None = None, arrive_by: datetime | None = None,
          party_size: int | None = None, constraints: dict[str, Any] | None = None) -> dict[str, Any]:
    """두 장소 사이 이동을 판정한다. `origin` · `dest` 는 `as_place` 가 만든 모양. 시각은 시간대가 있는 값이어야 한다(`depart_at` · `arrive_by` 중 하나만 — 없으면 `now` 출발).

    ★이 함수는 어디에도 쓰지 않는다 — 읽기다. 판정기를 못 쓰는 이유는 결과의 `reason` 에 그대로 남는다."""
    if depart_at is not None and arrive_by is not None:
        raise ValueError("depart_at 과 arrive_by 는 둘 중 하나만 줄 수 있다")
    tz = (depart_at or arrive_by or now).tzinfo
    head = {"from": origin["name"], "to": dest["name"], "checked_at": now.isoformat(), "mode": "arrive_by" if arrive_by is not None else "depart_at"}
    if not (_in_seoul(origin) and _in_seoul(dest)):                    # ★판정기 · 근거에 닿기 전에 거른다
        return {**head, "basis": None, "status": "out_of_scope", "grade": "none", "grade_label": GRADE_LABELS["none"],
                "reason": {"code": "out_of_scope", "reason": "이 서비스는 서울만 다뤄요 — 서울 밖 장소는 판정하지 않아요"}}
    basis = _safe_basis()
    head["basis"] = basis
    try:
        leg = legs.leg_planner(party_size, constraints or {})
    except TeamUnavailable:
        raise
    except Exception:                                                  # noqa: BLE001 — 판정기를 못 만들면 「못 쓴다」
        logger.exception("move judge: leg planner could not be built")
        if current_bindings() is not None:
            raise TeamUnavailable("mobility", "engine_unavailable") from None
        return _unavailable(head, origin, dest, "engine_error", "이동 판정기를 쓰는 중 오류가 났어요")
    if leg is None:
        if current_bindings() is not None:
            raise TeamUnavailable("mobility", "engine_unavailable")
        why = f"이동 판정기가 꺼져 있거나 쓸 수 없어요(상태: {(basis or {}).get('mode', '알 수 없음')})"
        return _unavailable(head, origin, dest, "engine_unavailable", why)
    try:
        if arrive_by is not None:
            got, why = leg(origin, dest, arrive_by, None)
            searched, fallback = None, False
        else:
            got, why, searched, fallback = _depart_at(leg, origin, dest, depart_at or now)
        if got is not None:
            if not _valid(got):
                raise ValueError("판정기가 이상한 모양을 돌려줬다")
            out = _judged(got, tz=tz)
    except TeamUnavailable:
        raise
    except Exception:                                                  # noqa: BLE001 — 판정기 오류는 500 이 아니라 「못 쓴다」
        logger.exception("move judge: engine failed")
        if current_bindings() is not None:
            raise TeamUnavailable("mobility", "engine_unavailable") from None
        return _unavailable(head, origin, dest, "engine_error", "이동 판정 중 오류가 났어요")
    if got is None:
        reason = _reason(why)
        undetermined = reason["code"] in _UNDETERMINED
        if undetermined:
            reason["reason"] = f"{reason['reason']} (판정기가 판단하지 못했다는 뜻이에요 — 갈 방법이 없다는 뜻이 아니에요)"
        return {**head, "status": "undetermined" if undetermined else "no_route", "grade": "none", "grade_label": GRADE_LABELS["none"], "reason": reason,
                **({"searched": searched} if searched else {})}
    if depart_at is not None or arrive_by is None:
        requested = depart_at or now
        out["requested_depart_at"] = requested.isoformat()
        out["wait_min"] = max(0, int(round((got["starts_at"] - requested).total_seconds() / 60)))
        if fallback:
            out["earliest_not_guaranteed"] = True
    return {**head, **out}


def _unavailable(head: dict[str, Any], origin: dict[str, Any], dest: dict[str, Any], code: str, reason: str) -> dict[str, Any]:
    return {**head, "status": "unavailable", "grade": "estimate", "grade_label": GRADE_LABELS["estimate"],
            "reason": {"code": code, "reason": reason}, "estimate": _estimate(origin, dest)}


def _depart_at(leg: Callable[..., Any], origin: dict[str, Any], dest: dict[str, Any], start: datetime) -> tuple[Any, Any, str | None, bool]:
    """도착 목표를 넓혀 가며(`_TARGET_STEPS_MIN`) 첫 성립 경로를 찾고, 그 소요에 맞춘 목표로 한 번 더 판정해 출발을 당긴다. → `(결과, 이유, 어디까지 봤나, 첫 결과로 대신했나)`."""
    first, why = None, None
    for minutes in _TARGET_STEPS_MIN:
        first, why = leg(origin, dest, start + timedelta(minutes=minutes), start)
        if first is not None:
            break
    if first is None:
        return None, why, f"출발 후 {_TARGET_STEPS_MIN[-1]}분 안에 도착하는 목표까지만 확인했어요", False
    target = start + timedelta(minutes=minutes)
    buffer = max(0, int(round((target - first["ends_at"]).total_seconds() / 60))) if isinstance(first.get("ends_at"), datetime) else 0
    second, _ = leg(origin, dest, start + timedelta(minutes=first["eta_min"] + buffer), start)
    return (second or first), None, None, second is None


def _reason(why: Any) -> dict[str, Any]:
    if isinstance(why, dict):
        return _scrub({"code": str(why.get("code") or "no_route"), "reason": why.get("reason") or "판정기가 경로를 내지 못했어요",
                       **({"earliest": why["earliest"]} if why.get("earliest") else {})})
    return {"code": "no_route", "reason": "판정기가 경로를 내지 못했어요"}


__all__ = ["GRADE_LABELS", "InvalidPlace", "as_place", "judge"]

"""Request-local service connections; candidate assembly never edits live tables."""
from __future__ import annotations

from contextlib import contextmanager
from contextvars import ContextVar
from dataclasses import dataclass
from functools import wraps
import logging
from types import MappingProxyType
from typing import Any, Mapping


@dataclass(frozen=True)
class BindingTable:
    values: Mapping[tuple[str, str], Any]
    registry: Any = None
    revision: str | None = None

    def __post_init__(self):
        object.__setattr__(self, "values", MappingProxyType(dict(self.values)))


_bound: ContextVar[BindingTable | None] = ContextVar("service_bindings", default=None)
_building: ContextVar[dict | None] = ContextVar("building_services", default=None)
_standalone: ContextVar[bool] = ContextVar("standalone_services", default=False)


@contextmanager
def standalone_services(enabled=True):
    """Explicit legacy seam for independently assembled components and their tests."""
    token = _standalone.set(enabled)
    try:
        yield
    finally:
        _standalone.reset(token)


@contextmanager
def collect_services():
    values: dict = {}
    token = _building.set(values)
    try:
        yield values
    finally:
        _building.reset(token)


def collect_registration(group: str, values: Mapping[str, Any]) -> bool:
    builder = _building.get()
    if builder is None:
        return False
    builder.update({(group, key): value for key, value in values.items()})
    return True


def collecting_services() -> bool:
    return _building.get() is not None


@contextmanager
def bind_services(table: BindingTable | None):
    if table is None or _bound.get() is not None:
        yield
        return
    token = _bound.set(table)
    try:
        yield
    finally:
        _bound.reset(token)


def current_bindings() -> BindingTable | None:
    return _bound.get()


def read_binding(group: str, key: str, legacy=None, *, required_team: str | None = None):
    table = _bound.get()
    if table is None:
        if _standalone.get():
            return legacy
        from app.core.team_availability import TeamUnavailable

        if required_team:
            raise TeamUnavailable(required_team, "composition_unbound")
        raise RuntimeError("service access requires a bound composition")
    value = table.values.get((group, key))
    if required_team:
        from app.core.team_availability import TeamUnavailable

        if table.registry is None:
            raise TeamUnavailable(required_team, "not_installed")
        table.registry.require_runnable(required_team)
        if value is None:
            raise TeamUnavailable(required_team, "not_installed")
    elif value is None:
        import logging

        logging.getLogger(__name__).info("optional_service_omitted", extra={
            "service_group": group, "service_key": key,
            "reason": "provider_unavailable", "composition_revision": table.revision})
    return value


def use_instance_bindings(method):
    @wraps(method)
    async def call(self, *args, **kwargs):
        with bind_services(getattr(self, "service_bindings", None)):
            table = current_bindings()
            outcome = "returned"
            try:
                return await method(self, *args, **kwargs)
            except BaseException:
                outcome = "raised"
                raise
            finally:
                logging.getLogger(__name__).info("controller_call_finished", extra={
                    "operation": method.__name__, "call_outcome": outcome,
                    "composition_revision": table.revision if table is not None else None,
                })
    return call


class PinCompositionMiddleware:
    """Hold a runtime snapshot through the complete ASGI/SSE response lifetime."""

    def __init__(self, app, runtime):
        self.app, self.runtime = app, runtime

    async def __call__(self, scope, receive, send):
        if scope["type"] not in {"http", "websocket"}:
            await self.app(scope, receive, send)
            return
        with self.runtime.pin():
            await self.app(scope, receive, send)

